requests.sync:
function (doc, oldDoc, meta) {
  // Offline-first action requests. A guest's phone may CREATE one, for itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("guest:" + oldDoc.guest_id); } return; }
  if (!doc.guest_id) { throw({forbidden: "guest_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.guest_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new requests must be 'pending'"}); }
    if (doc._id.indexOf("req::" + doc.guest_id + "::") !== 0) { throw({forbidden: "id must be req::<guest_id>::<uuid>"}); }
  } else {
    if (oldDoc.guest_id !== doc.guest_id) { throw({forbidden: "guest_id is immutable"}); }
    requireAdmin();
  }
  channel("guest:" + doc.guest_id);
}
